# Use Node.js to validate the YAML (it's always present since this is a Node project)
node -e "
const fs = require('fs');
// Basic sanity: confirm required top-level keys exist
const raw = fs.readFileSync('.github/workflows/ci.yml', 'utf8');
const checks = [
  ['push trigger',          raw.includes('push:')],
  ['pull_request trigger',  raw.includes('pull_request:')],
  ['main branch',           raw.includes('- main')],
  ['actions/checkout',      raw.includes('actions/checkout')],
  ['setup-node',            raw.includes('actions/setup-node')],
  ['npm ci',                raw.includes('npm ci')],
  ['ESLint step',           raw.includes('npm run lint')],
  ['Jest step',             raw.includes('npm test')],
  ['docker-build job',      raw.includes('docker-build:')],
  ['Docker main-only guard',raw.includes(\"github.ref == 'refs/heads/main'\")],
  ['docker/build-push',     raw.includes('docker/build-push-action')],
  ['needs: lint-and-test',  raw.includes('needs: lint-and-test')],
  ['concurrency cancel',    raw.includes('cancel-in-progress: true')],
  ['layer cache',           raw.includes('cache-from: type=gha')],
];
let pass = true;
checks.forEach(([name, ok]) => {
  console.log((ok ? '✓' : '✗') + '  ' + name);
  if (!ok) pass = false;
});
process.exit(pass ? 0 : 1);
"

node -e "
const fs = require('fs');
const raw = fs.readFileSync('.dockerignore', 'utf8');
const checks = [
  ['.env wildcard (.env.*)',     raw.includes('.env.*')],
  ['plain .env',                 raw.includes('\n.env\n') || raw.startsWith('.env\n')],
  ['*.env glob',                 raw.includes('*.env')],
  ['node_modules/',              raw.includes('node_modules/')],
  ['.git/ excluded',             raw.includes('.git/')],
  ['coverage/ excluded',         raw.includes('coverage/')],
  ['test files excluded',        raw.includes('*.test.js')],
  ['.github/ excluded',          raw.includes('.github/')],
];
let pass = true;
checks.forEach(([name, ok]) => {
  console.log((ok ? '✓' : '✗') + '  ' + name);
  if (!ok) pass = false;
});
process.exit(pass ? 0 : 1);
"

